export type StreamData = {
    body?: never;
    headers?: {
        /**
         * The cursor of the last event received. Sent automatically by browsers on reconnect; replays exactly what was missed.
         */
        'Last-Event-ID'?: string | null;
    };
    path?: never;
    query?: {
        /**
         * Comma-separated channel ids; absent means every channel the caller may read.
         */
        channels?: string;
        /**
         * Resume after this cursor; `Last-Event-ID` wins when both are sent.
         */
        cursor?: string;
        /**
         * Which device is connected, so its cursor advances as it reads.
         */
        device?: string;
    };
    url: '/api/v1/stream';
};

export type StreamErrors = {
    /**
     * No usable credential
     */
    401: Problem;
    /**
     * Not a device owner — service accounts read the inbox
     */
    403: Problem;
    /**
     * That cursor is not one of ours
     */
    422: Problem;
    /**
     * Too many live connections held by this principal on this replica (design §8.2)
     */
    429: Problem;
};

export type StreamError = StreamErrors[keyof StreamErrors];

export type StreamResponses = {
    /**
     * An event stream
     */
    200: unknown;
};

export type ListStreamsData = {
    body?: never;
    path?: never;
    query?: never;
    url: '/api/v1/streams';
};

export type ListStreamsErrors = {
    /**
     * No usable credential
     */
    401: Problem;
};

export type ListStreamsError = ListStreamsErrors[keyof ListStreamsErrors];

export type ListStreamsResponses = {
    /**
     * The connections
     */
    200: Array<Connection>;
};

export type ListStreamsResponse = ListStreamsResponses[keyof ListStreamsResponses];

export type DisconnectStreamData = {
    body?: never;
    path: {
        /**
         * The connection id
         */
        id: string;
    };
    query?: never;
    url: '/api/v1/streams/{id}';
};

export type DisconnectStreamErrors = {
    /**
     * No usable credential
     */
    401: Problem;
};

export type DisconnectStreamError = DisconnectStreamErrors[keyof DisconnectStreamErrors];

export type DisconnectStreamResponses = {
    /**
     * Disconnected, or already gone
     */
    204: void;
};

export type DisconnectStreamResponse = DisconnectStreamResponses[keyof DisconnectStreamResponses];

export type SyncData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Resume after this cursor. Absent replays everything still retained.
         */
        cursor?: string;
        /**
         * Comma-separated channel ids; absent means every channel the caller may read.
         */
        channels?: string;
        /**
         * Which device is catching up, so its cursor advances; absent for a one-off caller.
         */
        device?: string;
        /**
         * Page size, clamped server-side.
         */
        limit?: number;
    };
    url: '/api/v1/sync';
};

export type SyncErrors = {
    /**
     * No usable credential
     */
    401: Problem;
    /**
     * Not a device owner — service accounts read the inbox
     */
    403: Problem;
    /**
     * That cursor is not one of ours
     */
    422: Problem;
};

export type SyncError = SyncErrors[keyof SyncErrors];

export type SyncResponses = {
    /**
     * Events since the cursor, plus what expired while away
     */
    200: SyncPage;
};

export type SyncResponse = SyncResponses[keyof SyncResponses];

